<?php require_once __DIR__.'/../includes/functions.php';require_login('hospital');$pdo=db();$uid=current_user()['id'];$s=$pdo->prepare('SELECT * FROM hospitals WHERE user_id=? LIMIT 1');$s->execute([$uid]);$hospital=$s->fetch();$pageTitle='Hospital dashboard';require __DIR__.'/../includes/header.php';?>
<div class="dashboard-head"><div><span class="eyebrow">HOSPITAL PORTAL</span><h1>Hospital workspace</h1><p>Manage vaccine availability and update approved appointment outcomes.</p></div></div><?php if(!$hospital):?><div class="notice">Your account is active, but no hospital profile is linked yet. Ask the administrator to create a hospital record and set its <code>user_id</code> to <?= (int)$uid ?>.</div><section class="panel"><h2>Setup required</h2><p class="muted">The administrator should add the hospital name, address, city, contact details, and link this account in the hospitals table. See README for the SQL example.</p></section><?php else:$s=$pdo->prepare("SELECT b.*,c.full_name child_name,v.name vaccine_name,u.name parent_name FROM bookings b JOIN children c ON c.id=b.child_id JOIN vaccines v ON v.id=b.vaccine_id JOIN users u ON u.id=b.parent_id WHERE b.hospital_id=? ORDER BY b.appointment_date DESC,b.appointment_time DESC");$s->execute([$hospital['id']]);$bookings=$s->fetchAll();$s=$pdo->prepare('SELECT hv.*,v.name vaccine_name,v.dose FROM hospital_vaccines hv JOIN vaccines v ON v.id=hv.vaccine_id WHERE hv.hospital_id=? ORDER BY v.name');$s->execute([$hospital['id']]);$availability=$s->fetchAll();?>
<div class="stat-grid"><div class="stat-card"><small>Hospital</small><strong style="font-size:20px"><?=e($hospital['name'])?></strong><span><?=e($hospital['city'])?></span></div><div class="stat-card"><small>Total appointments</small><strong><?=count($bookings)?></strong><span>Linked to your hospital</span></div><div class="stat-card"><small>Awaiting vaccination</small><strong><?=count(array_filter($bookings,fn($b)=>$b['status']==='approved'))?></strong><span>Approved bookings</span></div><div class="stat-card"><small>Completed</small><strong><?=count(array_filter($bookings,fn($b)=>$b['status']==='completed'))?></strong><span>Recorded outcomes</span></div></div>
<section class="panel"><div class="panel-head"><div><h2>Appointments</h2><p>Only bookings assigned to your hospital are shown.</p></div></div><div class="table-wrap"><table><thead><tr><th>Child / parent</th><th>Vaccine</th><th>Appointment</th><th>Status</th><th>Update</th></tr></thead><tbody><?php if(!$bookings):?><tr><td colspan="5" class="empty">No appointments assigned yet.</td></tr><?php endif;foreach($bookings as $b):?><tr><td><b><?=e($b['child_name'])?></b><br><small><?=e($b['parent_name'])?></small></td><td><?=e($b['vaccine_name'])?></td><td><?=e($b['appointment_date'])?> · <?=e(substr($b['appointment_time'],0,5))?></td><td><span class="badge <?=e($b['status'])?>"><?=e(ucfirst($b['status']))?></span></td><td><?php if($b['status']==='approved'):?><form method="post" action="<?=BASE_URL?>/hospital/actions.php" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="complete"><input type="hidden" name="booking_id" value="<?=$b['id']?>"><input name="notes" placeholder="Notes (optional)" maxlength="500" style="width:120px;padding:7px;border:1px solid var(--line);border-radius:7px"><button class="button small">Mark vaccinated</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><div class="panel-head"><div><h2>Vaccine availability</h2><p>Set availability for vaccines offered at your location.</p></div></div><?php if(!$availability):?><div class="notice">No vaccine availability has been configured. Ask your administrator to link vaccines to this hospital in the hospital_vaccines table.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Vaccine</th><th>Dose</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($availability as $v):?><tr><td><?=e($v['vaccine_name'])?></td><td><?=e($v['dose'])?></td><td><span class="badge <?=e($v['status'])?>"><?=e(ucfirst($v['status']))?></span></td><td><form method="post" action="<?=BASE_URL?>/hospital/actions.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="availability"><input type="hidden" name="vaccine_id" value="<?=$v['vaccine_id']?>"><button class="button small secondary" name="status" value="<?=$v['status']==='available'?'unavailable':'available'?>">Mark <?=$v['status']==='available'?'unavailable':'available'?></button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endif;?><?php require __DIR__.'/../includes/footer.php';?>
